  "Date mentioned": ["बताई गई तारीख़", "పేర్కొన్న తేదీ", "குறிப்பிட்ட தேதி", "ಉಲ್ಲೇಖಿಸಿದ ದಿನಾಂಕ", "പരാമർശിച്ച തീയതി"],
  "Thank-you email draft": ["धन्यवाद ईमेल मसौदा", "ధన్యవాద ఇమెయిల్ డ్రాఫ్ట్", "நன்றி மின்னஞ்சல் வரைவு", "ಧನ್ಯವಾದ ಇಮೇಲ್ ಡ್ರಾಫ್ಟ್", "നന്ദി ഇമെയിൽ ഡ്രാഫ്റ്റ്"],
  "Recipient email": ["प्राप्तकर्ता ईमेल", "గ్రహీత ఇమెయిల్", "பெறுநர் மின்னஞ்சல்", "ಸ್ವೀಕರಿಸುವವರ ಇಮೇಲ್", "സ്വീകർത്താവിന്റെ ഇമെയിൽ"],
  "Built only from your notes, the company, the role and your name. Review before sending; nothing is sent without your approval.": ["केवल आपके नोट्स, कंपनी, भूमिका और नाम से बना। भेजने से पहले जाँचें; आपकी मंज़ूरी के बिना कुछ नहीं भेजा जाता।", "మీ నోట్స్, కంపెనీ, పాత్ర, పేరు నుంచే రూపొందింది. పంపే ముందు సమీక్షించండి; మీ ఆమోదం లేకుండా ఏదీ పంపబడదు.", "உங்கள் குறிப்புகள், நிறுவனம், பதவி, பெயர் ஆகியவற்றிலிருந்து மட்டுமே. அனுப்பும் முன் பாருங்கள்; உங்கள் ஒப்புதல் இல்லாமல் எதுவும் அனுப்பப்படாது.", "ನಿಮ್ಮ ಟಿಪ್ಪಣಿ, ಕಂಪನಿ, ಪಾತ್ರ, ಹೆಸರಿನಿಂದ ಮಾತ್ರ ರಚಿತ. ಕಳುಹಿಸುವ ಮೊದಲು ಪರಿಶೀಲಿಸಿ; ನಿಮ್ಮ ಅನುಮೋದನೆ ಇಲ್ಲದೆ ಏನೂ ಕಳುಹಿಸಲಾಗುವುದಿಲ್ಲ.", "നിങ്ങളുടെ നോട്ടുകൾ, കമ്പനി, റോൾ, പേര് എന്നിവയിൽ നിന്ന് മാത്രം. അയക്കും മുമ്പ് പരിശോധിക്കുക; നിങ്ങളുടെ അനുമതിയില്ലാതെ ഒന്നും അയക്കില്ല."],
  "Send this thank-you email from your Gmail to {to}?": ["क्या यह धन्यवाद ईमेल आपके Gmail से {to} को भेजें?", "ఈ ధన్యవాద ఇమెయిల్‌ను మీ Gmail నుంచి {to} కు పంపాలా?", "இந்த நன்றி மின்னஞ்சலை உங்கள் Gmail இலிருந்து {to} க்கு அனுப்பவா?", "ಈ ಧನ್ಯವಾದ ಇಮೇಲ್ ಅನ್ನು ನಿಮ್ಮ Gmail ನಿಂದ {to} ಗೆ ಕಳುಹಿಸಬೇಕೇ?", "ഈ നന്ദി ഇമെയിൽ നിങ്ങളുടെ Gmail-ൽ നിന്ന് {to} ലേക്ക് അയക്കണോ?"],
  "Thank-you sent.": ["धन्यवाद ईमेल भेजा गया।", "ధన్యవాద ఇమెయిల్ పంపబడింది.", "நன்றி மின்னஞ்சல் அனுப்பப்பட்டது.", "ಧನ್ಯವಾದ ಇಮೇಲ್ ಕಳುಹಿಸಲಾಗಿದೆ.", "നന്ദി ഇമെയിൽ അയച്ചു."],
  "Sent": ["भेजा गया", "పంపబడింది", "அனுப்பப்பட்டது", "ಕಳುಹಿಸಲಾಗಿದೆ", "അയച്ചു"],
  "Copy": ["कॉपी", "కాపీ", "நகலெடு", "ನಕಲಿಸಿ", "പകർത്തുക"],
  "Copied.": ["कॉपी हुआ।", "కాపీ అయింది.", "நகலெடுக்கப்பட்டது.", "ನಕಲಿಸಲಾಗಿದೆ.", "പകർത്തി."],
  "Save draft": ["मसौदा सहेजें", "డ్రాఫ్ట్ సేవ్ చేయండి", "வரைவைச் சேமி", "ಡ್ರಾಫ್ಟ್ ಉಳಿಸಿ", "ഡ്രാഫ്റ്റ് സേവ് ചെയ്യുക"],
  "Send from my Gmail": ["मेरे Gmail से भेजें", "నా Gmail నుంచి పంపండి", "என் Gmail இலிருந்து அனுப்பு", "ನನ್ನ Gmail ನಿಂದ ಕಳುಹಿಸಿ", "എന്റെ Gmail-ൽ നിന്ന് അയക്കുക"],
  "Question bank": ["प्रश्न बैंक", "ప్రశ్నల బ్యాంక్", "கேள்வி வங்கி", "ಪ್ರಶ್ನೆ ಬ್ಯಾಂಕ್", "ചോദ്യ ബാങ്ക്"],
